#define FDIST 0.1
#define THICKNESS 0.25
#define PI 3.1415926
#define FLOOR_HEIGHT 10.

// raytrace a 2D box with outgoing normal
vec2 box2d(in vec2 ro, in vec2 rd, in vec2 r, out vec2 no) {
    vec2 dr = 1.0/rd;
    vec2 n = ro * dr;
    vec2 k = r * abs(dr);

    vec2 pout =  k - n;
    vec2 pin =  - k - n;
    float tout = min(pout.x, pout.y);
    float tin = max(pin.x, pin.y);
    no = -sign(rd) * step(pout.xy, pout.yx);
    return vec2(tin, tout);
}
#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
// Raytrace box, returns (t_in, t_out) and incident normal
vec2 box(in vec3 ro, in vec3 rd, in vec3 r, out vec3 no) {
    vec3 dr = 1.0/rd;
    vec3 n = ro * dr;
    vec3 k = r * abs(dr);

    vec3 pout =  k - n;
    vec3 pin =  - k - n;
    float tout = min(pout.x, min(pout.y, pout.z));
    float tin = max(pin.x, max(pin.y, pin.z));
    no = -sign(rd) * step(pin.zxy, pin.xyz) * step(pin.yzx, pin.xyz);
    return vec2(tin, tout);
}

//raytrace a wirebox (clean version without animations)

vec2 wirebox(in vec3 eye, in vec3 rd, in float r, in float thickness, out vec3 no) {
    vec2 t = box(eye, rd, vec3(r), no);
    //handle being inside (we need to trace our cavities from the face closest to the view point, instead of using the viewing direction at all)
    if (t.x <= 0. && t.y > 0.) {
        vec3 roa = abs(eye);
        no = step(roa.yzx, roa.xyz) * step(roa.zxy, roa.xyz);
    } else if (t.y < 0.) return t;

    float t_init = t.x;
    // trace the inner walls by tracing infinite rectangular shafts in each face, repeating this twice to produce the wireframe shape
    for (int i=0; i<2; ++i) {

        // transform the ray into tangent space to intersect it with a shaft perpendicular to the normal
        mat2x3 invproj = mat2x3(no.zxy, no.yzx);
        mat3x2 proj = transpose(invproj);
        vec2 n2;
        vec2 t2 = box2d(proj * eye, proj * rd, vec2(r-thickness), n2);

        // compare depths to see if we've hit the face outside where we've placed the shaft; if so, just render that surface and stop
        if (t2.y < t.x || (t2.x > t.x && t2.x > 0.)) {
            break;
        }
        t.x = t2.y;
        no = invproj * n2;
    }
    return t;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-0.5*iResolution.xy)/iResolution.x;

    vec4 O = fragColor;
    vec2 C=fragCoord;

    O=vec4(0);




    vec3 p,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1));  
    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(1),H(g*.1),.8)*2./e/8e3
    )
    {
        p=g*d;
     p.z-=iTime;
        a=30.;
        p=mod(p-a,a*2.)-a;
        s=2.;
        for(int i=0;i++<8;){
            p=.3-abs(p);
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.7+sin(iTime*.02)*.1;
            p=abs(p)*e-
                vec3(
                    5.*3.,
                    120,
                    8.*5.
                 );
         }
         g+=e=length(p.xzxz)/s;
    }

    vec3 eye;
    float eyetime = iTime * 0.6;
	float ang = eyetime * 0.5;
    float rad = 4. * (sin(eyetime)*.5+.5);
    if (iMouse.x > 0.) {
        float mouseY =  (0.5-iMouse.y/iResolution.y) * PI;
        float mouseX = -(iMouse.x/iResolution.x) * 2. * PI;
        eye = rad * vec3(cos(mouseX) * cos(mouseY), sin(mouseX) * cos(mouseY), sin(mouseY));
    } else {
        eye = rad * vec3(cos(ang), sin(ang), 0.3 * sin(ang/0.70752)+.3);
    }
    vec3 w = -normalize(eye);
    vec3 u = normalize(cross(w, vec3(0., 0., 1.)));
    vec3 v = cross(u, w);
    vec3 rd = normalize(u*uv.x + v*uv.y + FDIST * w);

    //trace the outer box
    vec3 n;

    vec2 t = wirebox(eye, rd, 1., THICKNESS, n);
    float objmask = step(t.x, t.y) * step(0., t.y);

    //trace the floor
    float tfloor = -(eye.z + FLOOR_HEIGHT)/rd.z;
    float floormask = step(0., tfloor) * step(-FLOOR_HEIGHT, eye.z);
    vec3 bgcol = floormask * vec3(.5, .7, .8);
    n = mix(vec3(0., 0., 1.), n, objmask+O.xyz);

    vec3 albedo = mix(bgcol, n*.5 + .5, objmask+O.xyz);

    //shadow & shading
    float lighttime = -iTime * 0.4;
    vec3 lightdir = normalize(vec3(.5 * cos(lighttime), .5 * sin(lighttime), 1.));
    vec3 hitpt = eye + mix(tfloor, t.x, objmask) +O.xyz;
    vec3 ns;
    vec2 ts = wirebox(hitpt + lightdir*1e-2, lightdir, 1., THICKNESS, ns);
    float shadowfac = 1.-step(ts.x, ts.y) * step(0., ts.y);
    shadowfac *= max(0., dot(n, lightdir));
    shadowfac = mix(0.025, shadowfac, shadowfac);
    vec3 col1 = albedo * shadowfac;
    vec3 col2 = albedo * max(0., dot(n, -lightdir)) * vec3(0.05, 0.07, 0.2);
    vec3 col = col1 ;


    fragColor = vec4(pow(col, vec3(0.5)), 1.);
}
